// The vendored wallet kit's rebuild check (issue 1615). The full rebuild runs
// in CI as `bun run check:appkit` (web-client.yml); this holds the pieces it
// rests on: the committed bundle names the pinned versions, and a change to
// either its banner or its generated bytes is reported, never passed.
import { describe, expect, test } from "bun:test";
import { existsSync, readFileSync } from "node:fs";
import { banner, bundlePath, compareBundles, readPins } from "../../vendor/rebuild-appkit.ts";

describe("rebuild-appkit", () => {
  const pins = readPins();
  const path = bundlePath(pins);

  test("the committed bundle exists under the pinned version's name", () => {
    expect(existsSync(path)).toBe(true);
  });

  test("its first line is the banner the pinned inputs give", () => {
    const committed = readFileSync(path, "utf8");
    expect(committed.slice(0, committed.indexOf("\n"))).toBe(banner(pins));
  });

  test("the same text passes", () => {
    const text = `${banner(pins)}\nvar a=1;export{a};\n`;
    expect(compareBundles(text, text)).toBeNull();
  });

  test("a changed generated byte fails", () => {
    const built = `${banner(pins)}\nvar a=1;export{a};\n`;
    expect(compareBundles(built, built.replace("a=1", "a=2"))).toContain("generated bytes differ");
  });

  test("a changed version banner fails as a banner mismatch", () => {
    const built = `${banner(pins)}\nvar a=1;export{a};\n`;
    const bumped = built.replace(`appkit ${pins.appkit}`, "appkit 0.0.1");
    expect(compareBundles(built, bumped)).toContain("version banner differs");
  });
});
